row.ariaRowIndex = row.index + 1;
// If this._view is a `TreeDataAdapter`, we should be able to get the view
// row object, and that'll be much faster than the other method below.
const viewRow = this._view.rowAt?.(row.index);
if (viewRow) {
  row.ariaLevel = viewRow.level + 1;
  row.ariaSetSize = viewRow.setSize;
  row.ariaPosInSet = viewRow.posInSet + 1;
  return;
}

const index = row.index;
const level = this._view.getLevel(index);
const rowCount = this._view.rowCount;

let topCount = 1;
for (let i = index - 1; i >= 0; i--) {
  const l = this._view.getLevel(i);
  if (l < level) {
    break;
  }
  if (l == level) {
    topCount++;
  }
}

let bottomCount = 0;
for (let i = index + 1; i < rowCount; i++) {
  const l = this._view.getLevel(i);
  if (l < level) {
    break;
  }
  if (l == level) {
    bottomCount++;
  }
}

row.ariaLevel = level + 1;
row.ariaSetSize = topCount + bottomCount;
row.ariaPosInSet = topCount;
